// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // the test contract is c's owner (msg.sender at construction) and the
    // recipient of every withdrawal, so it must accept ETH
    receive() external payable {}

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        // give the contract a fixed, ample balance so withdrawals always succeed
        uint256 total = 2 ether;
        vm.deal(address(c), total);

        // admissible domain: withdrawal of at most the whole balance (otherwise
        // BOTH versions legitimately revert on the transfer)
        vm.assume(amount <= address(c).balance);

        uint256 before = address(c).balance;

        c.withdraw(amount); // owner == this test contract, transfer to us succeeds

        // RULE: the caller receives exactly `amount`, so the contract's balance
        // drops by exactly `amount`.
        assertTrue(address(c).balance == before - amount);
    }
}
